// A decode worker. Several files are open in each worker, and many jobs can be pending on it.
// terminate() rejects every pending job and drops the files opened in the worker.
// cancel(job) asks the worker to stop one job; it rejects that job as cancelled.
export class DecodeWorker {
  constructor(port) {
    this.port = port;
  }

  post(job) {
    return this.port.request(job);
  }

  cancel(job) {
    return this.port.request({ op: 'cancel', id: job.id });
  }

  terminate() {
    this.port.close();
  }
}

