// Run jobs on decode workers, with a time limit per job.
export class Pool {
  constructor(spawn) {
    this.spawn = spawn;
    this.workers = [];
  }

  run(index, job, limit) {
    const worker = this.workers[index];
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error(job.name + ' timed out after ' + limit / 1000 + ' s'));
        this.restart(index);
      }, limit);
      worker.post(job).then(
        (value) => {
          clearTimeout(timer);
          resolve(value);
        },
        (error) => {
          clearTimeout(timer);
          reject(error);
        },
      );
    });
  }

  restart(index) {
    this.workers[index].terminate();
    this.workers[index] = this.spawn();
  }
}
